scwin.trigger1_onclick = function(e) {
    scwin.createDataMap();
};
scwin.trigger2_onclick = function(e) {
    for (var i = 0; i < 200; i++) {
        scwin.createDataMap();
    }
};
scwin.trigger3_onclick = function(e) {
    length = Object.keys(WebSquare.idCache).length;
};
scwin.trigger4_onclick = function(e) {
    remove("dataMap2");
    remove("dataMap3");
    remove("dataMap4");
    remove("dataMap5");
};
scwin.btnTest_onclick = function(e) {
    WebSquare.wUnit.getDomById('trigger2').click();
    WebSquare.wUnit.getDomById('trigger4').click();
    WebSquare.wUnit.getDomById('trigger3').click();
};
scwin.unitTest = function() {
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btnTest').click()");
    WebSquare.wUnit.addCommand("assert", "length >= 100", "false");
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.length = 0;
    dataMap1.setJSON({
        "key1": "test1",
        "key2": "test2"
    });
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
